  const n = f.fields[0].values.length;
  const out = [];
  for (let i = 0; i < n; i++) {
    const r = {};
    f.fields.forEach((c) => { r[c.name] = c.values[i] !== undefined ? c.values[i] : c.values.get(i); });
    out.push(r);
  }
  return out;
}
function semDados(msg) {
  return { title: { text: msg || 'Sem dados no período', left: 'center', top: 'middle', textStyle: { color: TEXTO2, fontSize: 13, fontWeight: 'normal' } } };
}
// Clareia uma cor hex em `fator` (0..1).
function clarear(hex, fator) {
  const n = parseInt(hex.slice(1), 16);
  const r = n >> 16, g = (n >> 8) & 255, b = n & 255;
  const f = (c) => Math.round(c + (255 - c) * fator);
  return '#' + [f(r), f(g), f(b)].map((c) => c.toString(16).padStart(2, '0')).join('');
}
function hm(seg) {
  if (seg === null || seg === undefined || isNaN(seg)) return '-';
  const h = Math.floor(seg / 3600), m = Math.round((seg % 3600) / 60);
  return h + ':' + String(m === 60 ? 59 : m).padStart(2, '0');
}
function num(v, casas) {
  if (v === null || v === undefined || isNaN(v)) return '-';
  return Number(v).toLocaleString('pt-BR', { maximumFractionDigits: casas === undefined ? 2 : casas });
}
function dataHora(ms) {
  if (!ms) return '-';
  return new Date(ms).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
}
function setVar(nome, valor) {
  const q = {}; q['var-' + nome] = valor;
  context.grafana.locationService.partial(q, true);
}
function eixoTempo() {
  return { type: 'value', name: 'tempo (h:mm)', position: 'right', nameTextStyle: { color: TEXTO2 },
           axisLabel: { color: TEXTO2, formatter: (v) => hm(v) }, splitLine: { show: false } };
}
function eixoConsumo() {
  return { type: 'value', name: UNIDADE, position: 'left', nameTextStyle: { color: TEXTO2 },
           axisLabel: { color: TEXTO2, formatter: (v) => num(v, 0) }, splitLine: { lineStyle: { color: GRADE } } };
}

// T2 — Árvore da raiz: nó = issue, tamanho = consumo, cor = status.
const rows = linhas(frame(0));
if (!rows.length) return semDados('Clique numa barra do "Custo por árvore" para abrir a árvore');
const por = {};
rows.forEach((r) => { por[r.issue] = { r, children: [] }; });
let raiz = null;
rows.forEach((r) => {
  if (r.nivel === 0) raiz = por[r.issue];
  else if (por[r.pai]) por[r.pai].children.push(por[r.issue]);
});
if (!raiz) return semDados();
const maxC = Math.max(...rows.map((r) => r.consumo || 0), 1);
const conv = (n) => ({
  name: `${n.r.board}/#${n.r.issue}`,
  value: n.r.consumo || 0,
  symbolSize: 8 + 26 * Math.sqrt((n.r.consumo || 0) / maxC),
  itemStyle: { color: STATUS_COR[n.r.status] || STATUS_COR['Desconhecida'], borderColor: STATUS_COR[n.r.status] },
  status: n.r.status, n_exec: n.r.n_exec, tempo: n.r.tempo_s,
  children: n.children.map(conv),
});
return {
  tooltip: { trigger: 'item', formatter: (p) => `<b>${p.data.name}</b> — ${p.data.status}<br/>Consumo: ${num(p.data.value)} ${UNIDADE}<br/>Execuções: ${p.data.n_exec} · Tempo: ${hm(p.data.tempo)}` },
  series: [{ type: 'tree', data: [conv(raiz)], top: '5%', left: '12%', bottom: '5%', right: '18%', initialTreeDepth: -1,
             label: { color: TEXTO, position: 'left', verticalAlign: 'middle', align: 'right' },
             leaves: { label: { position: 'right', align: 'left' } }, lineStyle: { color: TEXTO2 },
             expandAndCollapse: true, animationDurationUpdate: 600 }],
};
